// Store RPC response topic if present
if (msg.rpcResponseTopic) {
    flow.set("def_rpc_response_topic", msg.rpcResponseTopic);
}

// Send to both parallel reads
return [msg, msg];

// Battery, Grid, Load daily energy
// 514: Battery Charge
// 515: Battery Discharge
// 516-519: (skip)
// 520: Grid Import
// 521: Grid Export
// 522-525: (skip)
// 526: Load

msg.baseAddr = 514;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 514,
    quantity: 13  // 514-526
};
return msg;

// PV and Generator daily energy
// 529: PV Total
// 530: PV MPPT1
// 531: PV MPPT2
// 532: PV MPPT3
// 533: PV MPPT4
// 534-535: (skip)
// 536: Generator

msg.baseAddr = 529;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 529,
    quantity: 8  // 529-536
};
return msg;

// Build DailyEnergyFlowState from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("DailyEnergyFlowState: missing base address");
    return null;
}

// ---- Store partials ----

// Batt/Grid/Load 514-526
if (baseAddr === 514) {
    const battCharge = data[0] || 0;         // 514
    const battDischarge = data[1] || 0;      // 515
    const gridImport = data[6] || 0;         // 520
    const gridExport = data[7] || 0;         // 521
    const loadEnergy = data[12] || 0;        // 526

    flow.set("def_part_batt_grid_load", {
        chargeEnergyKWh: Math.round((battCharge * 0.1) * 10) / 10,
        dischargeEnergyKWh: Math.round((battDischarge * 0.1) * 10) / 10,
        importEnergyKWh: Math.round((gridImport * 0.1) * 10) / 10,
        exportEnergyKWh: Math.round((gridExport * 0.1) * 10) / 10,
        loadEnergyKWh: Math.round((loadEnergy * 0.1) * 10) / 10
    });
}

// PV/Gen 529-536
else if (baseAddr === 529) {
    const pvTotal = data[0] || 0;            // 529
    const pvMppt1 = data[1] || 0;            // 530
    const pvMppt2 = data[2] || 0;            // 531
    const pvMppt3 = data[3] || 0;            // 532
    const pvMppt4 = data[4] || 0;            // 533
    const genEnergy = data[7] || 0;          // 536

    flow.set("def_part_pv_gen", {
        pvTotalEnergyKWh: Math.round((pvTotal * 0.1) * 10) / 10,
        pvMppt1EnergyKWh: Math.round((pvMppt1 * 0.1) * 10) / 10,
        pvMppt2EnergyKWh: Math.round((pvMppt2 * 0.1) * 10) / 10,
        pvMppt3EnergyKWh: Math.round((pvMppt3 * 0.1) * 10) / 10,
        pvMppt4EnergyKWh: Math.round((pvMppt4 * 0.1) * 10) / 10,
        genEnergyKWh: Math.round((genEnergy * 0.1) * 10) / 10
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const battGridLoadPart = flow.get("def_part_batt_grid_load");
const pvGenPart = flow.get("def_part_pv_gen");

if (!battGridLoadPart || !pvGenPart) {
    return null;  // Wait for both
}

const deviceId = msg.deviceId
    || global.get("DEVICE_ID")
    || env.get("DEVICE_ID")
    || "EC100-DEV-001";

const state = {
    kind: "DailyEnergyFlowState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: deviceId,

    loadEnergyKWh: battGridLoadPart.loadEnergyKWh,

    grid: {
        importEnergyKWh: battGridLoadPart.importEnergyKWh,
        exportEnergyKWh: battGridLoadPart.exportEnergyKWh
    },

    pv: {
        totalEnergyKWh: pvGenPart.pvTotalEnergyKWh,
        mppt: [
            { id: 1, energyKWh: pvGenPart.pvMppt1EnergyKWh },
            { id: 2, energyKWh: pvGenPart.pvMppt2EnergyKWh },
            { id: 3, energyKWh: pvGenPart.pvMppt3EnergyKWh },
            { id: 4, energyKWh: pvGenPart.pvMppt4EnergyKWh }
        ]
    },

    battery: {
        chargeEnergyKWh: battGridLoadPart.chargeEnergyKWh,
        dischargeEnergyKWh: battGridLoadPart.dischargeEnergyKWh
    },

    generator: {
        energyKWh: pvGenPart.genEnergyKWh
    }
};

// Clear partials
flow.set("def_part_batt_grid_load", null);
flow.set("def_part_pv_gen", null);

// Get RPC response topic if present
const rpcResponseTopic = flow.get("def_rpc_response_topic");
flow.set("def_rpc_response_topic", null);

flow.set("dailyEnergyFlowStateSnapshot", state);

msg.payload = state;
msg.state = state;
msg.rpcResponseTopic = rpcResponseTopic;

return msg;

if (msg.rpcResponseTopic) {
    msg.topic = msg.rpcResponseTopic;
    return [msg, null];  // RPC response
} else {
    return [null, msg];  // MQTT telemetry
}
